// dispatch/execution-contract.mjs — pure validator for an agent-proposed
// INLINE execution contract (ADR-006 R3).
//
// Pure data module: no fs, no store writes, no network. Validates the
// ADR-006 §4 minimum inline-contract field set and fails closed (throws
// `RunnerConfigError`) on anything outside it.
//
// Two checks are deliberately redundant with the generic unknown-field gate
// below, because they are the single most safety-critical checks in this
// cell (ADR-006 §6 -- first slice is read-only only, no session/coordination
// reference this slice):
//   - `mutation: 'mutating'` is rejected by name, not merely because it maps
//     to an "unrecognized" value -- UNLESS the contract carries the
//     engine-reserved protocol-operation stamp (Phase 01 mutation-unlock,
//     R6a, `carriesProtocolOperationStamp` below), proof it was built by
//     session-engine.mjs's own mediated `dispatchDeclaredOperation` door and
//     not forged by a bare caller.
//   - `coordinationId` (and other session/coordination field names) is
//     rejected by name, not merely because it happens to be absent from the
//     accepted field set today -- so a future accidental addition to that
//     set could never silently re-admit one of these.
//
// Phase 01 mutation-unlock HIGH-finding fix (Red-Team, P01.1): the reserved
// stamp above proves an inline contract CLAIMS engine provenance, but
// `carriesProtocolOperationStamp` is a bare `string.startsWith()` check --
// forgeable by any caller that imports this module's own exported
// `PROTOCOL_OPERATION_STAMP_PREFIX` and hand-builds the string, bypassing
// session-engine.mjs's `dispatchDeclaredOperation`/`assertMutatingDispatchAllowed`
// entirely. `extractProtocolOperationStamp`/`resolveMutatingCwdPosture` below
// are the shared, pure(ish) R2/R3 predicates BOTH session-engine.mjs's own
// pre-check (fast, honest refusal before any work starts) and
// `assignment-runner.mjs`'s dispatch-layer re-verification (the real,
// unforgeable-by-caller gate, at the actual point mutation is honored) call
// -- so the two enforcement points can never independently drift. This adds
// read-only git inspection (via `../paths.mjs`) to this module, a narrow,
// deliberate exception to the "no fs" header above -- inspection only, never
// a contract-validation side effect, and never a write.

import { MODEL_POLICY_TIERS, RunnerConfigError } from './config.mjs';
import { resolveMainCheckoutRoot, resolveRepoRoot } from '../paths.mjs';
export const REPEAT_MODE_VALUES = Object.freeze(['pre-delivery', 'post-delivery']);
export const POLICY_PATCH_FIELDS = new Set([
  'rigor', 'tier', 'fallbackExecutors', 'visibility', 'repeatMode',
  'capability', 'distinctProviderFrom',
]);

export const CONTRACT_POLICY_VERSION = '1';

const RETIRED_SAVED_TIER_FIELD = ['min', 'Tier'].join('');

/**
 * Normalize the one retired persisted policy key at the load boundary.
 * Current producers and generic validation never accept or write it.
 */
export function normalizeSavedPolicyTier(policy, { allowAdditionalFields = false } = {}) {
  if (!isPlainObject(policy) || policy[RETIRED_SAVED_TIER_FIELD] === undefined) return policy;
  if (policy.tier !== undefined) fail(`saved policy cannot declare both "${RETIRED_SAVED_TIER_FIELD}" and "tier"`);
  const tier = policy[RETIRED_SAVED_TIER_FIELD];
  if (!MODEL_POLICY_TIERS.includes(tier)) {
    fail(`saved policy.${RETIRED_SAVED_TIER_FIELD} must be one of ${MODEL_POLICY_TIERS.join(', ')}`);
  }
  const remaining = Object.fromEntries(Object.entries(policy).filter(([key]) => key !== RETIRED_SAVED_TIER_FIELD));
  if (!allowAdditionalFields && Object.keys(remaining).length > 0) {
    fail(`saved contract.policy may contain only "${RETIRED_SAVED_TIER_FIELD}"`);
  }
  return Object.freeze({ ...remaining, tier });
}

// Phase 01 mutation-unlock (R6a): the ONE reserved `contract.constraints`
// namespace that marks an inline contract as ENGINE-derived operation
// provenance, minted exclusively by session-engine.mjs's own
// `buildSessionContract`/`assertNoReservedOperationStamp` mechanism for a
// declared `dispatchDeclaredOperation` call. Defined here (dispatch/infra
// layer) rather than in session-engine.mjs (coordination/use-case layer) so
// this module and assignment-normalizer.mjs -- both infra-layer, per
// docs/architecture-manifest.json -- never import upward from
// src/runner/coordination/** (the one-directional-layer rule
// test/architecture.test.mjs enforces); session-engine.mjs imports this
// constant from here instead of re-declaring it, so there is exactly one
// definition either side of the layer boundary trusts.
export const PROTOCOL_OPERATION_STAMP_PREFIX = 'protocol-operation:';

/** `true` when `constraints` carries at least one entry stamped with the
 * reserved `PROTOCOL_OPERATION_STAMP_PREFIX` namespace -- the one signal
 * that lets `validateExecutionContract` (below) and
 * `assignment-normalizer.mjs`'s `stampInlineAssignment` distinguish a
 * mutating inline contract session-engine.mjs itself built from one any
 * other caller could have forged by hand. */
export function carriesProtocolOperationStamp(constraints) {
  return Array.isArray(constraints) && constraints.some((entry) => typeof entry === 'string' && entry.startsWith(PROTOCOL_OPERATION_STAMP_PREFIX));
}

// `protocol-operation:${definitionId}@${definitionVersion}#${operationId}`
// -- the exact shape `session-engine.mjs`'s `protocolOperationStamp()` mints.
// `definitionId` is assumed to contain no `@`, and `definitionVersion` no
// `#` (true for every real FlowDefinition metadata.id/version, both plain
// slugs per `definitions/schema.mjs`); a stamp that violates that shape
// fails to match and is treated as absent -- fail closed, never a guess.
const PROTOCOL_OPERATION_STAMP_RE = /^([^@]+)@([^#]+)#(.+)$/;

/**
 * Parse the SINGLE `PROTOCOL_OPERATION_STAMP_PREFIX`-namespaced entry out of
 * `constraints` into `{ definitionId, definitionVersion, operationId }`.
 * Returns `null` -- never throws -- when zero or more than one such entry is
 * present, or the one present entry does not match the expected shape: a
 * missing/ambiguous/malformed stamp is exactly as unauthorized as no stamp
 * at all to this function's own callers (R2/R3 re-verification, below).
 *
 * @param {unknown} constraints
 * @returns {{definitionId: string, definitionVersion: string, operationId: string}|null}
 */
export function extractProtocolOperationStamp(constraints) {
  if (!Array.isArray(constraints)) return null;
  const matches = constraints.filter((entry) => typeof entry === 'string' && entry.startsWith(PROTOCOL_OPERATION_STAMP_PREFIX));
  if (matches.length !== 1) return null;
  const rest = matches[0].slice(PROTOCOL_OPERATION_STAMP_PREFIX.length);
  const m = PROTOCOL_OPERATION_STAMP_RE.exec(rest);
  if (!m) return null;
  const [, definitionId, definitionVersion, operationId] = m;
  return { definitionId, definitionVersion, operationId };
}

/**
 * `true` when a declared operation's own resolved definition (`operation`,
 * as returned by `definition.spec.operations.find(...)`) declares
 * `result.kind: 'work-product'` (Phase 01 mutation-unlock R2). Shared,
 * trivial predicate -- both session-engine.mjs's pre-check and
 * assignment-runner.mjs's dispatch-layer re-verification read the SAME
 * field the SAME way.
 *
 * @param {object|undefined|null} operation
 * @returns {boolean}
 */
export function operationDeclaresWorkProduct(operation) {
  return Boolean(operation) && operation.result?.kind === 'work-product';
}

/**
 * Resolve whether `cwd` is safe for a mutating dispatch (Phase 01
 * mutation-unlock R3): it must resolve to a LINKED git worktree, never the
 * main checkout, and never fail open on an unresolvable root. Never throws
 * itself -- returns a descriptor so each caller (session-engine.mjs's
 * `CoordinationError`, assignment-runner.mjs's `RunnerConfigError`) can
 * report the SAME underlying resolution outcome in its own idiomatic error
 * type/message without this module depending on either.
 *
 * The exact comparison (Phase 01's own direct investigation, unchanged by
 * this fix): `resolveMainCheckoutRoot(cwd) === resolveRepoRoot(cwd)` --
 * i.e. the toplevel of `cwd` IS the main checkout root -- refuses, since
 * `cwd` may legitimately be a SUBDIRECTORY of either the main checkout or a
 * worktree (comparing against raw `cwd` would wrongly refuse that case).
 * `resolveMainCheckoutRoot` never throws by its own documented contract
 * (returns `null` outside any git checkout) -- no defensive try/catch
 * around it here (Reviewer LOW finding, P01.1: the pre-fix code carried one
 * around this exact call, dead since the function it wrapped never throws).
 *
 * @param {string|undefined} cwd
 * @returns {{ok: true, mainCheckoutRoot: string, repoRoot: string}
 *   | {ok: false, reason: 'outside-git'}
 *   | {ok: false, reason: 'unresolvable', error: Error}
 *   | {ok: false, reason: 'main-checkout', repoRoot: string}}
 */
export function resolveMutatingCwdPosture(cwd) {
  const mainCheckoutRoot = resolveMainCheckoutRoot(cwd);
  if (mainCheckoutRoot === null) {
    return { ok: false, reason: 'outside-git' };
  }
  let repoRoot;
  try {
    repoRoot = resolveRepoRoot(cwd);
  } catch (err) {
    return { ok: false, reason: 'unresolvable', error: err };
  }
  if (mainCheckoutRoot === repoRoot) {
    return { ok: false, reason: 'main-checkout', repoRoot };
  }
  return { ok: true, mainCheckoutRoot, repoRoot };
}

const ACCEPTED_CONTRACT_FIELDS = new Set([
  'objective',
  'contextRefs',
  'constraints',
  'expectedOutputs',
  'mutation',
  'evidence',
  'role',
  'capabilities',
  'budget',
  // ADR-007 §1/§3: the operation id an inline contract claims to support,
  // when it is attached to a Work at a declared Stage. Format-check only
  // here (non-empty string when present) -- this generic, domain-ignorant
  // validator never knows what a legal operation id is; that semantic
  // legality check belongs solely to the domain harness seam
  // (domains/coding/harness/enrich-and-validate-contract.mjs), which the
  // foundation calls strictly after this validator (ADR-007 §2).
  'supports',
  // `contract.policy` may carry EXACTLY one key (`tier`), never
  // `preferExecutor`/`preferPersona`/`model`/`visibility`/`fallbackExecutors`.
  // Unit I04 / Phase 3: FlowDefinition task.contractTemplate reference for
  // operation prompt template resolution at dispatch time. Format-check only
  // here (non-empty string when present).
  'contractTemplate',
  'policy',
]);

const ACCEPTED_CALLER_FIELDS = new Set(['writerId', 'parentAssignmentId', 'coordination']);
const ACCEPTED_COORDINATION_CALLER_FIELDS = new Set(['fanOutPayload', 'actionInvocation']);
const ACTION_INVOCATION_KINDS = new Set([
  'dispatch-operation', 'authorize-and-dispatch', 'record-disposition',
  'record-human-turn', 'link-contribution', 'fan-out',
]);
const NORMALIZED_STEP_FIELDS = new Set([
  'type', 'as', 'operationId', 'targetActorId', 'nodeId', 'objective',
  'expectedOutputs', 'contextRefs', 'constraints', 'capabilities',
  'fromAssignmentId', 'intent', 'round', 'taskKey', 'mutation',
  'authorizationId', 'invocationKey', 'reason', 'grantedContextRefs',
  'targetArtifactRef', 'targetRef', 'disposition', 'rationale', 'evidenceRefs',
  'turnId', 'turnOrdinal', 'channel', 'artifactRef', 'externalRef',
  'attributedTo', 'respondsToRefs', 'contributionId', 'contributionType',
  'assignmentId', 'roundKey', 'anchors', 'respondsTo', 'branches',
  'fromAssignmentId', 'omittedFields',
]);
const ACCEPTED_BUDGET_FIELDS = new Set(['timeoutMs', 'maxRuns', 'tokens']);
const ACCEPTED_EVIDENCE_FIELDS = new Set(['required']);
// Step 08 P04.2b: see the `'policy'` entry in ACCEPTED_CONTRACT_FIELDS above
// for why this exists and why it is exactly one field wide.
//
// M12: still deliberately narrower than a full PolicyPatch -- this inline
// contract's own `policy` field is `tier` alone. Cross-checked against schema.mjs's
// POLICY_PATCH_FIELDS so a future removal is caught.
const ACCEPTED_POLICY_FIELDS = new Set(['tier']);
for (const field of ACCEPTED_POLICY_FIELDS) {
  if (!POLICY_PATCH_FIELDS.has(field)) {
    throw new Error(`execution-contract.mjs's ACCEPTED_POLICY_FIELDS names "${field}", which schema.mjs's POLICY_PATCH_FIELDS no longer recognizes as a legal PolicyPatch field -- these two lists have drifted.`);
  }
}

// ADR-006 §6: no session or coordination reference in this slice.
const FORBIDDEN_SESSION_FIELDS = new Set(['coordinationId', 'sessionId', 'threadId', 'coordinationRef']);

const EVIDENCE_REQUIRED_VALUES = new Set(['reported', 'verified']);

// The id charset and length of the session identity contract
// (packages/session-identity/contracts/session-identity.resolve.v1.json
// x-idPattern / x-maxIdLength; a test keeps the two equal). This is a
// format-only floor against garbage caller.writerId values -- NOT a real
// identity check, and this module deliberately never calls
// resolveWriterIdentity() itself (stays pure, no process shell-out; see the
// module header and buildInlineAssignment in ./assignment.mjs for why).
export const WRITER_ID_RE = /^[A-Za-z0-9._-]+$/;
export const MAX_WRITER_ID_LENGTH = 200;

function fail(reason) {
  throw new RunnerConfigError(`execution-contract: ${reason}`);
}

function isPlainObject(value) {
  return Boolean(value) && typeof value === 'object' && !Array.isArray(value);
}

function isNonEmptyString(value) {
  return typeof value === 'string' && value.trim() !== '';
}

function isStringArray(value) {
  return Array.isArray(value) && value.every((v) => typeof v === 'string');
}

function assertNoForbiddenFields(obj, label) {
  for (const key of Object.keys(obj)) {
    if (FORBIDDEN_SESSION_FIELDS.has(key)) {
      fail(`${label} carries a forbidden session/coordination field "${key}" -- no session reference in this slice (ADR-006 §6)`);
    }
  }
}

function assertOnlyAcceptedFields(obj, accepted, label) {
  for (const key of Object.keys(obj)) {
    if (!accepted.has(key)) {
      fail(`${label} has unknown field "${key}"`);
    }
  }
}

/**
 * Validate an inline execution contract plus its caller provenance against
 * the ADR-006 §4 minimum field set (ADR-006 R3). Throws `RunnerConfigError`
 * for any violation. Returns nothing on success -- the caller already holds
 * the validated `contract`/`caller` objects it passed in.
 *
 * @param {object} params
 * @param {object} params.contract Agent-proposed execution contract
 * @param {object} params.caller Caller provenance ({ writerId, parentAssignmentId? })
 */
export function validateExecutionContract({ contract, caller } = {}) {
  if (!isPlainObject(contract)) {
    fail('contract must be a non-null object');
  }

  assertNoForbiddenFields(contract, 'contract');
  assertOnlyAcceptedFields(contract, ACCEPTED_CONTRACT_FIELDS, 'contract');

  if (!isNonEmptyString(contract.objective)) {
    fail('contract.objective must be a non-empty string');
  }

  if (!isStringArray(contract.contextRefs)) {
    fail('contract.contextRefs must be an array of strings (bounded context references)');
  }

  if (!isStringArray(contract.constraints)) {
    fail('contract.constraints must be an array of strings (constraints/authority)');
  }

  if (!isStringArray(contract.expectedOutputs) || contract.expectedOutputs.length === 0) {
    fail('contract.expectedOutputs must be a non-empty array of strings');
  }

  // ADR-006 §6: the single most safety-critical check in this module --
  // first slice is read-only only, UNLESS the contract carries the
  // engine-reserved protocol-operation stamp (Phase 01 mutation-unlock,
  // R6a) -- proof this exact contract was built by session-engine.mjs's
  // own mediated `dispatchDeclaredOperation` door, never a bare caller
  // forging `mutation: 'mutating'` by hand. Named explicitly, not folded
  // into the generic "must equal read-only" branch below, so each failure
  // mode always reports its own, distinct reason.
  if (contract.mutation === 'mutating') {
    if (!carriesProtocolOperationStamp(contract.constraints)) {
      fail(
        'contract.mutation "mutating" is rejected -- only an inline contract carrying the engine-reserved protocol-operation stamp in its constraints (session-engine.mjs\'s own mediated dispatchDeclaredOperation door) may declare "mutating"; every other caller stays read-only-only (ADR-006 §6)',
      );
    }
  } else if (contract.mutation !== 'read-only') {
    fail('contract.mutation must be "read-only" or "mutating" (missing, or any other value, is rejected)');
  }

  if (!isPlainObject(contract.evidence)) {
    fail('contract.evidence must be an object with a "required" field');
  }
  assertOnlyAcceptedFields(contract.evidence, ACCEPTED_EVIDENCE_FIELDS, 'contract.evidence');
  if (!EVIDENCE_REQUIRED_VALUES.has(contract.evidence.required)) {
    fail('contract.evidence.required must be "reported" or "verified"');
  }

  if (!isNonEmptyString(contract.role)) {
    fail('contract.role must be a non-empty string (role hint)');
  }
  if (contract.supports !== undefined && !isNonEmptyString(contract.supports)) {
    fail('contract.supports must be a non-empty string when provided (an operation id it claims to support -- legality against the Work\'s declared Stage is checked by the domain harness seam, ADR-007 §3, not here)');
  }
  if (contract.contractTemplate !== undefined && !isNonEmptyString(contract.contractTemplate)) {
    fail('contract.contractTemplate must be a non-empty string when provided');
  }
  if (contract.capabilities !== undefined && !isStringArray(contract.capabilities)) {
    fail('contract.capabilities must be an array of strings when provided (capability hints)');
  }

  // `contract.policy` is optional and current contracts carry exactly
  // `tier`. Retired persisted keys are normalized before this validator at
  // the assignment load boundary, never accepted on a new contract.
  if (contract.policy !== undefined) {
    if (!isPlainObject(contract.policy)) {
      fail('contract.policy must be an object when provided');
    }
    assertOnlyAcceptedFields(contract.policy, ACCEPTED_POLICY_FIELDS, 'contract.policy');
    if (!MODEL_POLICY_TIERS.includes(contract.policy.tier)) {
      fail(`contract.policy.tier must be one of ${MODEL_POLICY_TIERS.join(', ')}`);
    }
  }

  if (!isPlainObject(contract.budget)) {
    fail('contract.budget must be an object');
  }
  assertOnlyAcceptedFields(contract.budget, ACCEPTED_BUDGET_FIELDS, 'contract.budget');
  if (!Number.isInteger(contract.budget.timeoutMs) || contract.budget.timeoutMs <= 0) {
    fail('contract.budget.timeoutMs must be a positive integer (milliseconds) -- the only enforced time budget');
  }
  if (!Number.isInteger(contract.budget.maxRuns) || contract.budget.maxRuns <= 0) {
    fail('contract.budget.maxRuns must be a positive integer -- the only enforced run-count budget');
  }
  if (contract.budget.tokens !== undefined && (typeof contract.budget.tokens !== 'number' || !Number.isFinite(contract.budget.tokens) || contract.budget.tokens < 0)) {
    fail('contract.budget.tokens must be a non-negative finite number when provided (telemetry only, never enforced as a limit)');
  }

  if (!isPlainObject(caller)) {
    fail('caller must be a non-null object');
  }
  assertNoForbiddenFields(caller, 'caller');
  assertOnlyAcceptedFields(caller, ACCEPTED_CALLER_FIELDS, 'caller');
  if (!isNonEmptyString(caller.writerId)) {
    fail('caller.writerId must be a non-empty string');
  }
  if (caller.writerId.length > MAX_WRITER_ID_LENGTH || !WRITER_ID_RE.test(caller.writerId)) {
    fail(`caller.writerId must match ${WRITER_ID_RE} and be at most ${MAX_WRITER_ID_LENGTH} characters (format-only floor, not an identity check)`);
  }
  if (caller.parentAssignmentId !== undefined && !isNonEmptyString(caller.parentAssignmentId)) {
    fail('caller.parentAssignmentId must be a non-empty string when provided');
  }
  if (caller.coordination !== undefined) {
    if (!isPlainObject(caller.coordination)) fail('caller.coordination must be an object when provided');
    assertOnlyAcceptedFields(caller.coordination, ACCEPTED_COORDINATION_CALLER_FIELDS, 'caller.coordination');
    if (caller.coordination.fanOutPayload !== undefined) {
      if (!isPlainObject(caller.coordination.fanOutPayload)) fail('caller.coordination.fanOutPayload must be an object when provided');
      const payload = caller.coordination.fanOutPayload;
      for (const field of ['actorId', 'objective', 'taskKey']) {
        if (!isNonEmptyString(payload[field])) fail(`caller.coordination.fanOutPayload.${field} must be a non-empty string`);
      }
      if (!isStringArray(payload.expectedOutputs) || payload.expectedOutputs.length === 0) fail('caller.coordination.fanOutPayload.expectedOutputs must be a non-empty array of strings');
      if (!isStringArray(payload.constraints)) fail('caller.coordination.fanOutPayload.constraints must be an array of strings');
      if (payload.capabilities !== undefined && !isStringArray(payload.capabilities)) fail('caller.coordination.fanOutPayload.capabilities must be an array of strings when provided');
      for (const field of ['fromAssignmentId', 'intent']) {
        if (payload[field] !== undefined && !isNonEmptyString(payload[field])) fail(`caller.coordination.fanOutPayload.${field} must be a non-empty string when provided`);
      }
    }
    if (caller.coordination.actionInvocation !== undefined) {
      const invocation = caller.coordination.actionInvocation;
      if (!isPlainObject(invocation)) fail('caller.coordination.actionInvocation must be an object when provided');
      assertOnlyAcceptedFields(invocation, new Set(['actionKey', 'kind', 'normalizedSteps']), 'caller.coordination.actionInvocation');
      if (!isNonEmptyString(invocation.actionKey) || !invocation.actionKey.startsWith('sha256:')) {
        fail('caller.coordination.actionInvocation.actionKey must be a sha256 action key');
      }
      if (!ACTION_INVOCATION_KINDS.has(invocation.kind)) {
        fail('caller.coordination.actionInvocation.kind is not a supported coordination action kind');
      }
      if (!Array.isArray(invocation.normalizedSteps) || invocation.normalizedSteps.length === 0) {
        fail('caller.coordination.actionInvocation.normalizedSteps must be a non-empty array');
      }
      for (const step of invocation.normalizedSteps) {
        if (!isPlainObject(step)) fail('caller.coordination.actionInvocation.normalizedSteps entries must be objects');
        assertOnlyAcceptedFields(step, NORMALIZED_STEP_FIELDS, 'caller.coordination.actionInvocation.normalizedSteps[]');
        if (step.omittedFields !== undefined && !isStringArray(step.omittedFields)) {
          fail('caller.coordination.actionInvocation.normalizedSteps[].omittedFields must be an array of strings when provided');
        }
      }
    }
  }
}

// dispatch/herdr-round.mjs -- the herdr-specific half of a terminal attempt's controller.
//
// An interactive agent runs in a herdr pane as an attempt of the run supervisor: the controller prepares
// what only it can (the brief on disk, the confinement homes, the folder-trust entry, the pane the
// terminal-control port allocates for the attempt's key) and hands the attempt over; everything after the
// handover -- starting the agent in the pane, waiting for its prompt, typing the brief, watching the
// outbox, the deadlines, ending the agent, settling and releasing the pane -- belongs to the supervisor
// and the gate, which keep going when this process is gone (docs/specs/runner.md).
//
// Three refusals shaped what stays here, each because doing the opposite failed in measured production:
//
// 1. The prompt never travels as keystrokes through a shell. It goes to disk; the supervisor types what
//    the brief file holds (the whole brief, or a one-line pointer to it) at the agent.
//
// 2. `agent_status` never concludes a round. Completion is the worker's own `outbox/result-<round>.json`
//    existing, and nothing else.
//
// 3. A failed attempt keeps its pane. That screen is the only place the reason is still legible; the
//    supervisor releases the pane with `retain` unless the attempt ended cleanly.

import path from 'node:path';
import fs from 'node:fs';
import os from 'node:os';
import { DispatchError } from './dispatch-error.mjs';
import { terminalRouteConfig } from '../../terminal-control/config.mjs';
import { normalizeAgentName } from './herdr-agent.mjs';
import { createRoundTerminalControl, portKey, slotDisplay, refusalError } from './terminal-slot.mjs';
import { briefPaths, renderBrief, renderPointer } from './brief.mjs';
import { writeVisibility } from './visibility-session.mjs';
import { createWorkerHome, removeWorkerHome, redactWorkerHome } from './worker-home.mjs';
import {
  seedTrust, seedCodexTrust, seedAgyTrust, defaultAgySettingsPath,
  seedCodexHookTrust, trustRoots,
} from './trust-store.mjs';
export { trustRoots };
import { ensureWorkerSession, DEFAULT_WORKER_SESSION } from './worker-session-boot.mjs';
import { normalizeLegacyConfinement } from './confinement/policies.mjs';
import { evaluateBypassPairing } from './confinement/bypass-pairing.mjs';
import { expandCredentialHome } from './provider-capacity.mjs';
import { publishMutableProjection } from './proof-helpers.mjs';
import { TRUST_CONTEXT_FILE, cleanupTrust } from '../../run-supervisor/steps/cleanup-trust.mjs';

/**
 * The variables a pane sets for the program in it: the terminal type and the identity of the pane, tab
 * and herdr server. The gate (which runs in the pane) keeps its own; the controller's -- another pane, or
 * none -- must not reach the agent, and `HERDR_SOCKET_PATH` of the operator's cockpit in particular would
 * hand a confined seat the cockpit.
 */
const PANE_TERMINAL_ENV = Object.freeze(['TERM', 'COLORTERM', 'TERM_PROGRAM', 'TERM_PROGRAM_VERSION']);

/** `env` without what a pane sets for its own program. */
export function withoutPaneEnv(env) {
  return Object.fromEntries(Object.entries(env ?? {}).filter(([name]) => !PANE_TERMINAL_ENV.includes(name) && !name.startsWith('HERDR_')));
}

/** How long an agent may show no progress before the supervisor stops it. Applies only when the runner
 * config sets no `idleTimeoutMs` (which also governs cli-spawn, where silence is normal). */
export const DEFAULT_IDLE_TIMEOUT_MS = 300000;

/** After a result file appeared while the supervisor is gone, how long the gate still waits for the
 * agent to finish its report before it ends the domain. */
export const ORPHAN_SETTLE_MS = 5000;

/**
 * One round's identity, plus the two things every step below does with it.
 *
 * `note` leaves a trace. Every binding is written BEFORE it is used, so a
 * dispatch process that dies mid-flight still leaves behind enough to find
 * what it started. It is never a gate: a visibility write that fails must not
 * take a working dispatch down with it, so it cannot throw.
 *
 * `fail` builds the error a caller can act on. `paneId` is unknown when a
 * round starts and belongs on every failure once it is known, which is why
 * this is one object rather than two free functions.
 */
function openRound({ runDir, workId, tier, model, agentName }) {
  const round = {
    runDir,
    workId,
    tier,
    model,
    agentName,
    paneId: null,
    // The terminal-control key of the pane, so a later close finds it by key.
    terminalKey: null,
    // The herdr session the pane lives in, so a later reaper or recovery asks the right server.
    herdrSession: null,
    // True only when this round wrote a trust entry, so teardown removes what it wrote and
    // never an entry a person vouched for.
    trustWritten: false,
    note(patch) {
      try { writeVisibility(runDir, patch); } catch { /* a courtesy, not a contract */ }
    },
    fail(errorClass, reason, message, extra = {}) {
      return new DispatchError(errorClass, message, {
        workId, tier, model, reason, runDir, agentName, paneId: round.paneId, terminalKey: round.terminalKey, herdrSession: round.herdrSession, ...extra,
      });
    },
  };
  return round;
}

/**
 * Apply declared confinement, before anything is launched.
 *
 * Two measures, and neither closes the hole alone. A private HOME closes the
 * `$HOME/.config/herdr/herdr.sock` fallback a worker would otherwise find
 * with no environment variable at all. It does NOT stop the worker reaching
 * the cockpit, because herdr injects `HERDR_SOCKET_PATH` into every pane it
 * creates and overwrites any override -- measured. What that leaves is the
 * one thing that does work: put the worker in a different session, so the
 * socket it is handed controls only worker panes.
 *
 * Declared, never inferred. An executor that declares nothing keeps the old
 * behaviour exactly, and Confinement Authority (`executeThroughConfinement`,
 * src/runner/dispatch/confinement/authority.mjs) has already refused any
 * `bypass` that did not declare all three confinement flags before this
 * function is ever reached on the real dispatch path.
 *
 * Confinement that was asked for and cannot be delivered is a refusal, not a
 * downgrade: running anyway would put a worker on the operator's cockpit
 * socket while the profile claims it is confined. The bypass-pairing and
 * `ownWorktree` checks below are backstops for callers that invoke this
 * adapter directly (bypassing Authority, as some tests do) -- not a second
 * policy implementation: the bypass-pairing check calls the exact same
 * `evaluateBypassPairing` function Authority itself calls
 * (confinement/bypass-pairing.mjs), so both entry points refuse an
 * incomplete pairing identically.
 */
export async function establishConfinement({ confinement, round, fullEnv, cwd, repoRoot, permissionMode, herdrBin }) {
  const normalized = confinement ? normalizeLegacyConfinement(confinement, `executor.${round.workId}.confinement`) : null;
  const effectiveConfinement = normalized ?? confinement;

  const hasOwnWorktree = Boolean(
    effectiveConfinement?.ownWorktree ||
    effectiveConfinement?.controls?.workspace === 'own',
  );
  const hasPrivateHome = Boolean(
    effectiveConfinement?.privateHome ||
    effectiveConfinement?.controls?.home === 'private',
  );
  const hasIsolatedSession = Boolean(
    effectiveConfinement?.isolatedSession ||
    effectiveConfinement?.controls?.session === 'isolated',
  );

  // Checked before ownWorktree/repoRoot, because an incomplete bypass pairing
  // is a refusal regardless of where the dispatch happens to be running.
  const { satisfied: bypassPairingSatisfied, missing: missingBypassControls } = evaluateBypassPairing({
    isBypass: permissionMode === 'bypass',
    hasOwnWorktree,
    hasPrivateHome,
    hasIsolatedSession,
  });
  if (!bypassPairingSatisfied) {
    throw round.fail('invalid-config', 'bypass-confinement-incomplete',
      `executor for work "${round.workId}" refused: permissionMode "bypass" requires full confinement (missing: ${missingBypassControls.join(', ')}).`);
  }

  // Checked next, because it is the one flag that is already true or already
  // false before anything is provisioned: a worker confined to its own
  // worktree cannot be running in the checkout it was told to stay out of.
  if (hasOwnWorktree && repoRoot && path.resolve(cwd) === path.resolve(repoRoot)) {
    throw round.fail('invalid-config', 'own-worktree-unavailable',
      `executor for work "${round.workId}" refused: confinement declares ownWorktree, but this dispatch runs in the repo root itself (${path.resolve(cwd)}) rather than a worktree of its own.`);
  }

  let workerHomePath = null;
  try {
    if (hasPrivateHome) {
      const home = createWorkerHome(os.tmpdir(), {
        runId: round.agentName,
        sourceHome: fullEnv.HOME ?? os.homedir(),
        workspacePath: path.resolve(cwd),
        repoRoot: repoRoot ?? path.resolve(cwd),
        permissionMode: permissionMode ?? 'ask',
      });
      workerHomePath = home.homePath;
      round.note({ workerHome: workerHomePath });
    }
    if (hasIsolatedSession) {
      // One worker session, never named by config: a config-supplied name could
      // point at the operator's own cockpit whenever that cockpit has a name
      // and the dispatch runs outside herdr, where there is no HERDR_SESSION
      // to compare it against.
      const session = await ensureWorkerSession(DEFAULT_WORKER_SESSION, {
        callerEnv: fullEnv,
        herdrBin,
      });
      round.note({ workerSession: session.sessionName });
      return { workerHomePath, sessionEnv: session.env, confined: true, status: 'confined' };
    }
    if (hasPrivateHome) {
      return { workerHomePath, sessionEnv: fullEnv, confined: true, status: 'confined' };
    }
    if (hasOwnWorktree) {
      return { workerHomePath: null, sessionEnv: fullEnv, confined: false, status: 'partial' };
    }
    return { workerHomePath: null, sessionEnv: fullEnv, confined: false, status: 'unconfined' };
  } catch (err) {
    if (workerHomePath) { try { removeWorkerHome(workerHomePath); } catch { /* nothing left to do */ } }
    throw round.fail('invalid-config', err.code ?? 'confinement-unavailable',
      `executor for work "${round.workId}" refused: confinement was declared but could not be established: ${err.message}`);
  }
}

/**
 * Pre-trust the workspace, or the agent stops at a folder-trust dialog with
 * nobody there to answer it and herdr reports `agent_not_ready`. Measured for
 * claude and codex; agy shows the same dialog under its own private HOME
 * (`~/.agy-homes/<x>/settings.json`, never the operator's own
 * `~/.gemini/...`), which is why the HOME to seed is resolved from the
 * executor's own env rather than the machine default -- seeding the wrong
 * HOME leaves agy's dialog exactly where it was. `trustStore` is still
 * DECLARED per executor, not assumed for everyone: an agent kind fgOS has
 * not measured a dialog for is not given an entry it may never have needed.
 *
 * Never throws. Refusing here would be worse than trying: the agent may
 * already be trusted by some other route, and the dialog it might still hit
 * is reported by name by the very next step anyway.
 */
export function seedWorkspaceTrust({ trustStore, round, cwd, repoRoot, fullEnv, workerEnv = null, accountSource = null }) {
  const projectPath = path.resolve(cwd);
  const roots = trustRoots(projectPath, repoRoot ?? path.dirname(projectPath));
  const stores = trustStorePaths({ trustStore, fullEnv, workerEnv, accountSource });
  let firstError = null;
  for (const root of roots) {
    try {
      let wrote;
      if (trustStore.kind === 'codex-toml') {
        wrote = seedCodexTrust(stores.target, { projectPath, repoRoot: root, rootConfigPath: stores.root });
        // Only into a worker's own private home: hook trust is never written to the account's real config.
        if (stores.target !== stores.root) seedHookTrust({ round, target: stores.target, projectPath, repoRoot: root, rootConfigPath: stores.root });
      } else if (trustStore.kind === 'agy' || trustStore.kind === 'agy-json') {
        wrote = seedAgyTrust(stores.target, { projectPath, repoRoot: root, rootSettingsPath: stores.root });
      } else {
        wrote = seedTrust(stores.target, { projectPath, repoRoot: root });
      }
      // A seed that finds the entry already there wrote nothing: the person (or an earlier
      // round) owns it, so this round must not remove it on teardown.
      if (wrote) {
        round.trustWritten = true;
        round.note({ trustSeeded: trustStore.kind });
      }
      return;
    } catch (err) {
      firstError ??= err;
    }
  }
  round.note({ trustSeedFailed: firstError?.message ?? 'no trust root to derive from' });
}

/** codex hook review is a second dialog after folder trust; seed it from the same trusted root.
 * Never throws: a failure is noted and the review it would have cleared is reported by name. */
function seedHookTrust({ round, target, projectPath, repoRoot, rootConfigPath }) {
  try {
    const { keys, skipped } = seedCodexHookTrust(target, { projectPath, repoRoot, rootConfigPath });
    if (keys.length) round.note({ hookTrustSeeded: keys.length });
    if (skipped) round.note({ hookTrustSkipped: skipped });
  } catch (err) {
    round.note({ hookTrustSeedFailed: err.message });
  }
}


/**
 * Where the trust decision is read (the account's real store) and where the
 * entry is written. They differ only for a confined worker with a private
 * home: it reads its store from the private CODEX_HOME / HOME, which starts
 * empty, so the entry goes there and the account's own store is never touched.
 *
 * `accountSource` is the credential source of the account the capacity layer
 * leased for this round. A private home carries THAT account's login, so the
 * decision is read from that account's own store, not from the account the
 * invocation's static env names: the two differ whenever the capacity layer
 * picks another account of the same provider, and the static one may never
 * have been asked about this repo. Without a private home the CLI reads the
 * invocation's home, so the leased account says nothing about it.
 */
export function trustStorePaths({ trustStore, fullEnv, workerEnv, accountSource = null }) {
  if (trustStore.kind === 'codex-toml') {
    const own = workerEnv?.CODEX_HOME && workerEnv.CODEX_HOME !== fullEnv.CODEX_HOME;
    const leased = own && accountSource?.kind === 'codex-home' ? expandCredentialHome(accountSource.home) : null;
    const real = trustStore.path ?? path.join(leased ?? fullEnv.CODEX_HOME ?? path.join(os.homedir(), '.codex'), 'config.toml');
    return { root: real, target: own ? path.join(workerEnv.CODEX_HOME, 'config.toml') : real };
  }
  if (trustStore.kind === 'agy' || trustStore.kind === 'agy-json') {
    const own = workerEnv?.HOME && workerEnv.HOME !== fullEnv.HOME;
    const leased = own && accountSource?.kind === 'home-files' ? expandCredentialHome(accountSource.home) : null;
    const real = trustStore.path ?? defaultAgySettingsPath(leased ?? fullEnv.HOME ?? os.homedir());
    return { root: real, target: own ? defaultAgySettingsPath(workerEnv.HOME) : real };
  }
  const real = trustStore.path ?? path.join(os.homedir(), '.claude.json');
  return { root: real, target: real };
}

/**
 * What typed at the agent: `inline` is the default so a person watching the pane sees the full brief in
 * the TUI conversation; `file-pointer` types a one-line pointer to `brief-<round>.md` on disk. The text
 * is written to a file the supervisor reads, so the same bytes reach the agent whoever delivers them.
 */
function writeTypedBrief({ delivery, briefText, runDir, roundNumber, paths }) {
  if (delivery !== 'file-pointer') return paths.briefPath;
  const typedPath = path.join(runDir, `brief-${roundNumber}.pointer.txt`);
  fs.writeFileSync(typedPath, renderPointer({ runDir, round: roundNumber }));
  return typedPath;
}

/**
 * The folder-trust entry for this attempt, written into the store the agent reads, and the record the
 * `cleanup-trust` step needs to take it back when the attempt is over. The record exists only when this
 * call wrote the entry, so an entry a person vouched for is never removed.
 */
function seedAttemptTrust({ trustStore, round, runDir, cwd, repoRoot, fullEnv, workerEnv, accountSource }) {
  seedWorkspaceTrust({ trustStore, round, cwd, repoRoot, fullEnv, workerEnv, accountSource });
  if (!round.trustWritten) return;
  const { target } = trustStorePaths({ trustStore, fullEnv, workerEnv });
  publishMutableProjection(path.join(runDir, TRUST_CONTEXT_FILE), {
    v: 1, kind: trustStore.kind, target, projectPath: path.resolve(cwd),
  });
}

/**
 * Everything a terminal attempt needs before its supervisor can start, in the order that makes every
 * failure leave nothing behind but the pane's key: the stale-result check, the brief, the confinement
 * homes, the pane, the trust entry.
 *
 * Returns what the envelope names (`briefPath`, `outboxDir`, `slot`), the herdr endpoint the supervisor
 * is started with, and `abandon()`: what a controller that fails before the handover calls to give the
 * pane back and take the credential and the trust entry out again. After the handover none of it is the
 * controller's: the supervisor releases the pane and the steps remove the trust entry.
 */
export async function prepareTerminalAttempt(ctx) {
  const {
    attemptId, runDir: rawRunDir, cwd, repoRoot, prompt, workId, tier, model, runId,
    herdrBin, fullEnv, confinement, permissionMode, agentKind, delivery = 'inline',
    trustStore, trustAccountSource, attemptEnv, dispatchBatchKey, anchorPaneId, terminalConfig,
  } = ctx;
  const roundNumber = 1;
  const runDir = path.resolve(rawRunDir);
  const paths = briefPaths(runDir, roundNumber);

  // The key is the attempt id itself: the supervisor addresses the pane by it, and a key the port would
  // rewrite could never be found again.
  const key = portKey(attemptId);
  if (key !== attemptId) {
    throw new DispatchError('invalid-config', `attempt id "${attemptId}" is not usable as a terminal key`, { workId, tier, model, reason: 'terminal-key-invalid', runDir });
  }

  fs.mkdirSync(paths.outbox, { recursive: true });
  // A run directory that already holds this round's result would settle the attempt before the agent just
  // briefed has done anything. The result file outranks everything; what it cannot know is whether the
  // file belongs to THIS round, and this is the only place that distinction still exists.
  if (fs.existsSync(paths.resultPath)) {
    throw new DispatchError(
      'invalid-config',
      `executor for work "${workId}" refused: ${paths.resultPath} already exists before this round started, so the attempt would settle on somebody else's result. Use a fresh run directory or a new round.`,
      { workId, tier, model, reason: 'stale-result-in-run-dir', runDir, resultPath: paths.resultPath },
    );
  }

  const agentName = normalizeAgentName(`fgos-${runId ?? workId ?? 'run'}-${attemptId}`);
  const round = openRound({ runDir, workId, tier, model, agentName });
  round.terminalKey = key;

  const rawContract = ctx.effectiveContract ?? null;
  const effectiveContract = rawContract
    ? {
        ...rawContract,
        resultClaim: rawContract.resultClaim
          ? { ...rawContract.resultClaim, path: paths.resultPath }
          : { path: paths.resultPath, schema: 'agent-result.v1', required: true },
      }
    : null;
  const briefText = renderBrief({ prompt, round: roundNumber, runDir, agentName, effectiveContract });
  fs.writeFileSync(paths.briefPath, briefText);
  if (effectiveContract && fs.existsSync(paths.effectiveExecutionContractPath)) {
    try { publishMutableProjection(paths.effectiveExecutionContractPath, effectiveContract); } catch { /* the brief already names the claim path */ }
  }
  const briefPath = writeTypedBrief({ delivery, briefText, runDir, roundNumber, paths });
  round.note({ status: 'requested', agentName, round: roundNumber, terminalKey: key });

  const { workerHomePath, sessionEnv, confined, status } = await establishConfinement({
    confinement, round, fullEnv, cwd, repoRoot, permissionMode, herdrBin,
  });
  round.note({ confinement: { status, confined } });
  round.herdrSession = sessionEnv?.HERDR_SESSION ?? null;
  if (round.herdrSession) round.note({ herdrSession: round.herdrSession });

  const projectRoot = repoRoot ?? cwd;
  const groupKey = portKey(dispatchBatchKey ?? runId ?? workId ?? key);
  const tc = createRoundTerminalControl({
    herdrBin,
    herdrEnv: sessionEnv,
    config: { ...terminalRouteConfig(projectRoot), ...(terminalConfig ?? {}) },
  });
  const display = slotDisplay({ groupKey, agent: agentKind, model });

  const abandon = async () => {
    try { await tc.releaseAsync({ key, groupKey, disposition: 'close' }); } catch { /* the pane is the port's to reconcile */ }
    try { await cleanupTrust({ runDir }); } catch { /* a leftover entry costs one line in the store */ }
    if (workerHomePath) { try { redactWorkerHome(workerHomePath); } catch { /* nothing further to do about a home we cannot read */ } }
  };

  try {
    // A pane already sitting in the caller's own tab joins the group, so the batch opens beside it. A pane
    // that cannot be taken is no anchor: the group simply opens its own tab.
    if (anchorPaneId) {
      try { tc.attach({ key: portKey(`anchor-${groupKey}`), pane: anchorPaneId, groupKey, display }); } catch { /* no anchor */ }
    }
    let slot;
    try {
      slot = await tc.allocateAsync({ key, groupKey, display, cwd, env: {} });
    } catch (err) {
      throw round.fail('worker-spawn-fail', err.code ?? 'pane_split_failed',
        `executor failed to start for work "${workId}": terminal-control could not open a pane (${err.code ?? 'unknown'}): ${err.message}`);
    }
    if (slot.result !== 'slot') {
      const err = refusalError(slot, `allocate ${key}`);
      throw round.fail('worker-spawn-fail', err.code === 'terminal_unknown' ? 'pane_split_failed' : err.code,
        `executor failed to start for work "${workId}": terminal-control could not open a pane (${err.code}): ${err.message}`);
    }
    round.paneId = slot.slot.paneId;
    round.note({ status: 'pane-created', paneId: round.paneId });

    // A confined run with a private home needs no seeding: that home is provisioned with the workspace
    // already trusted, so writing to the operator's own store for a directory only the worker will ever
    // see would be pure side effect.
    if (trustStore && !workerHomePath) {
      seedAttemptTrust({ trustStore, round, runDir, cwd, repoRoot, fullEnv, workerEnv: attemptEnv ?? null, accountSource: trustAccountSource ?? null });
    }
  } catch (err) {
    await abandon();
    throw err;
  }

  // One line so a person watching the runner's own stderr can find the pane to watch and the directory
  // this round's files will appear in. Diagnostic only -- nothing reads it back.
  process.stderr.write(`fgos: herdr-spawn work=${workId} pane=${round.paneId} agent=${agentName} runDir=${runDir}\n`);

  return {
    briefPath,
    outboxDir: paths.outbox,
    resultPath: paths.resultPath,
    slot: { key, groupKey },
    paneId: round.paneId,
    workerHomePath,
    // The herdr endpoint the supervisor reaches the pane through: the session this round lives in.
    endpointEnv: {
      ...(herdrBin ? { FGOS_HERDR_BIN: herdrBin } : {}),
      ...Object.fromEntries(Object.entries(sessionEnv ?? {}).filter(([name, value]) => name.startsWith('HERDR_') && typeof value === 'string')),
    },
    tc,
    display,
    abandon,
  };
}

/** Lines of `next` that `previous` did not already show: the screen scrolled, so the overlap is the longest
 * tail of `previous` that opens `next`. */
export function screenDelta(previous, next) {
  const before = String(previous ?? '').split('\n');
  const after = String(next ?? '').split('\n');
  for (let overlap = Math.min(before.length, after.length); overlap > 0; overlap -= 1) {
    if (before.slice(before.length - overlap).every((line, index) => line === after[index])) {
      return after.slice(overlap).join('\n');
    }
  }
  return after.join('\n');
}

const SCREEN_FOLLOW_MS = 3000;

/**
 * Show a person who watches the controller what the pane shows, from the moment the attempt is bound
 * until `stop()`. Display only: a screen that cannot be read is skipped, and nothing is concluded from it.
 */
export function followPaneScreen({ tc, key, onChunk, intervalMs = SCREEN_FOLLOW_MS }) {
  if (typeof onChunk !== 'function') return () => {};
  let previous = '';
  const look = () => {
    try {
      const seen = tc.read({ key, source: 'visible' });
      if (seen.result !== 'screen') return;
      const delta = screenDelta(previous, seen.screen).replace(/\s+$/, '');
      previous = seen.screen;
      if (delta.trim()) onChunk('stdout', `${delta}\n`);
    } catch { /* the pane is gone or busy: nothing to show */ }
  };
  const timer = setInterval(look, intervalMs);
  timer.unref?.();
  return () => clearInterval(timer);
}

